INPUT: block family B over point set P = {0,...,n-1}
OUTPUT: exact expected cover time E[T]

procedure EXPECTED_COVER_TIME(B, P):
    total <- 0                      # exact rational
    for k from 1 to |P|:
        sign <- (+1 if k odd else -1)
        for each k-subset S of P:
            c <- count of blocks b in B with (b ∩ S) nonempty
            if c > 0:
                total <- total + sign * |B| / c     # exact fraction
    return total

